package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="audit_log")
public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="actor_id") private Long actorId; private String action; @Column(name="entity_type") private String entityType; @Column(name="entity_id") private Long entityId; private LocalDateTime timestamp = LocalDateTime.now(); @Column(length=5000) private String details; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getActorId(){return actorId;} public void setActorId(Long actorId){this.actorId=actorId;} public String getAction(){return action;} public void setAction(String action){this.action=action;} public String getEntityType(){return entityType;} public void setEntityType(String entityType){this.entityType=entityType;} public Long getEntityId(){return entityId;} public void setEntityId(Long entityId){this.entityId=entityId;} public LocalDateTime getTimestamp(){return timestamp;} public void setTimestamp(LocalDateTime timestamp){this.timestamp=timestamp;} public String getDetails(){return details;} public void setDetails(String details){this.details=details;} }
